/**
 * 3D Garba Raas Arena using Three.js
 * Features:
 * - Sacred Mandvi (Garbi) with flickering 3D Diya, Shrifal & Marigold Garland
 * - Concentric rings of 3D Dancers in Chaniya Choli & Kediyu holding Dandiya sticks
 * - Synchronized BPM choreography, twirls, knee-bends and Dandiya clacks
 * - Dynamic Rangoli Cloth Floor matching 10 fabric themes & circular seek progress
 * - Floating festive particles, lanterns, raycasting dancer clicks & camera presets
 */

import * as THREE from 'three';

export class GarbaScene3D {
  constructor({ container, onDancerClick, onFloorSeek }) {
    this.container = container;
    this.onDancerClick = onDancerClick;
    this.onFloorSeek = onFloorSeek;

    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.controls = null;

    // Theme & State
    this.theme = null;
    this.isPlaying = false;
    this.bpm = 118;
    this.progress = 0; // 0..1
    this.crowdCount = 98000;

    // Dancers
    this.dancers = [];
    this.dancerGroup = null;
    this.userAvatar = null;

    // Floor & Mandvi
    this.floorMesh = null;
    this.floorCanvas = null;
    this.floorTexture = null;
    this.progressRingMesh = null;
    this.mandviGroup = null;
    this.diyaLight = null;
    this.flameMesh = null;

    // Particle Systems
    this.petalParticles = null;
    this.sparkParticles = null;

    // Animation & Raycaster
    this.clock = new THREE.Clock();
    this.raycaster = new THREE.Raycaster();
    this.mouse = new THREE.Vector2();
    this.animId = null;

    // Camera target transitions
    this.cameraTarget = new THREE.Vector3(0, 3, 0);
    this.desiredCameraPos = new THREE.Vector3(0, 18, 30);
    this.cameraMode = 'arena'; // 'arena', 'mandvi', 'dancer', 'topdown'

    // Mouse drag controls for smooth Orbit
    this.isDragging = false;
    this.prevMousePos = { x: 0, y: 0 };
    this.spherical = { radius: 36, theta: Math.PI / 4, phi: Math.PI / 3 };

    this.init();
  }

  init() {
    // 1. Scene & Camera
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x140c33, 0.015);

    const aspect = this.container.clientWidth / this.container.clientHeight;
    this.camera = new THREE.PerspectiveCamera(48, aspect, 0.1, 1000);
    this.updateCameraFromSpherical();

    // 2. WebGL Renderer
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
    this.renderer.setSize(this.container.clientWidth, this.container.clientHeight);
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.15;
    this.container.appendChild(this.renderer.domElement);

    // 3. Lighting
    this.setupLighting();

    // 4. Sacred Mandvi (Garbi & Diya)
    this.buildSacredMandvi();

    // 5. Floor & Circular Progress
    this.buildFloor();

    // 6. Rings of Dancers
    this.buildDancers();

    // 7. Festive Particles & Hanging Lanterns
    this.buildAtmosphere();

    // 8. Event Listeners
    this.setupEvents();

    // 9. Start Render Loop
    this.animate = this.animate.bind(this);
    this.animate();
  }

  setupLighting() {
    // Ambient moon / night glow
    this.ambientLight = new THREE.AmbientLight(0xfff2e0, 0.7);
    this.scene.add(this.ambientLight);

    // Warm overhead festive key light
    this.keyLight = new THREE.DirectionalLight(0xffecd0, 1.2);
    this.keyLight.position.set(15, 30, 20);
    this.keyLight.castShadow = true;
    this.keyLight.shadow.mapSize.width = 2048;
    this.keyLight.shadow.mapSize.height = 2048;
    this.keyLight.shadow.camera.near = 1;
    this.keyLight.shadow.camera.far = 100;
    this.keyLight.shadow.camera.left = -25;
    this.keyLight.shadow.camera.right = 25;
    this.keyLight.shadow.camera.top = 25;
    this.keyLight.shadow.camera.bottom = -25;
    this.scene.add(this.keyLight);

    // Warm Diya point light at the Mandvi center
    this.diyaLight = new THREE.PointLight(0xff9900, 3.5, 35, 1.2);
    this.diyaLight.position.set(0, 3.8, 0);
    this.diyaLight.castShadow = true;
    this.scene.add(this.diyaLight);

    // Festive rim light
    this.rimLight = new THREE.DirectionalLight(0x8a2be2, 0.6);
    this.rimLight.position.set(-20, 15, -20);
    this.scene.add(this.rimLight);
  }

  /* ─────────────────────────────────────────────────────────────
     Sacred Mandvi (Garbi) Centerpiece
     ───────────────────────────────────────────────────────────── */

  buildSacredMandvi() {
    this.mandviGroup = new THREE.Group();

    // Multi-tiered carved wooden / marble pedestal
    const baseMat = new THREE.MeshStandardMaterial({
      color: 0x2e1808,
      roughness: 0.5,
      metalness: 0.2
    });

    const tier1 = new THREE.Mesh(new THREE.CylinderGeometry(4.2, 4.6, 0.4, 32), baseMat);
    tier1.position.y = 0.2;
    tier1.receiveShadow = true;
    this.mandviGroup.add(tier1);

    const tier2 = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 3.8, 0.4, 32), baseMat);
    tier2.position.y = 0.6;
    tier2.receiveShadow = true;
    this.mandviGroup.add(tier2);

    // Marigold Garland (Genda Phool) Ring
    const flowerRingGroup = new THREE.Group();
    const petalColors = [0xff9900, 0xffbb00, 0xff5500, 0xffd700];
    const flowerCount = 36;
    for (let i = 0; i < flowerCount; i++) {
      const angle = (i / flowerCount) * Math.PI * 2;
      const flowerGeo = new THREE.DodecahedronGeometry(0.24, 1);
      const flowerMat = new THREE.MeshStandardMaterial({
        color: petalColors[i % petalColors.length],
        roughness: 0.8
      });
      const flower = new THREE.Mesh(flowerGeo, flowerMat);
      flower.position.set(Math.cos(angle) * 3.4, 0.85, Math.sin(angle) * 3.4);
      flower.rotation.set(Math.random(), Math.random(), Math.random());
      flowerRingGroup.add(flower);
    }
    this.mandviGroup.add(flowerRingGroup);

    // Handcrafted Earthen / Brass Garbi Pot (Matka with Perforated Holes)
    const potMat = new THREE.MeshStandardMaterial({
      color: 0x8b3a12, // Rich terracotta
      roughness: 0.4,
      metalness: 0.35
    });

    const potBody = new THREE.Mesh(new THREE.SphereGeometry(1.6, 32, 24), potMat);
    potBody.position.y = 2.4;
    potBody.castShadow = true;
    potBody.receiveShadow = true;
    this.mandviGroup.add(potBody);

    // Pot Neck & Rim
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.3, 0.8, 32), potMat);
    neck.position.y = 3.6;
    this.mandviGroup.add(neck);

    const rim = new THREE.Mesh(new THREE.TorusGeometry(1.0, 0.16, 16, 32), new THREE.MeshStandardMaterial({
      color: 0xd4af37, // Gold trim rim
      roughness: 0.25,
      metalness: 0.85
    }));
    rim.position.y = 4.0;
    rim.rotation.x = Math.PI / 2;
    this.mandviGroup.add(rim);

    // Auspicious Mango Leaves (Amra Pallav)
    const leafMat = new THREE.MeshStandardMaterial({ color: 0x1b7340, roughness: 0.6 });
    for (let i = 0; i < 7; i++) {
      const leafAngle = (i / 7) * Math.PI * 2;
      const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.22, 1.2, 5), leafMat);
      leaf.position.set(Math.cos(leafAngle) * 0.75, 4.3, Math.sin(leafAngle) * 0.75);
      leaf.rotation.x = 0.5 * Math.sin(leafAngle);
      leaf.rotation.z = -0.5 * Math.cos(leafAngle);
      this.mandviGroup.add(leaf);
    }

    // Sacred Coconut (Shrifal)
    const coconut = new THREE.Mesh(new THREE.SphereGeometry(0.65, 24, 20), new THREE.MeshStandardMaterial({
      color: 0x5a3d28,
      roughness: 0.9
    }));
    coconut.scale.set(0.9, 1.2, 0.9);
    coconut.position.y = 4.6;
    this.mandviGroup.add(coconut);

    // Auspicious Golden Swastik / Om Plates around the Pot
    for (let i = 0; i < 4; i++) {
      const angle = (i / 4) * Math.PI * 2;
      const disc = new THREE.Mesh(new THREE.CircleGeometry(0.35, 16), new THREE.MeshStandardMaterial({
        color: 0xffd700,
        metalness: 0.9,
        roughness: 0.2,
        side: THREE.DoubleSide
      }));
      disc.position.set(Math.cos(angle) * 1.62, 2.4, Math.sin(angle) * 1.62);
      disc.rotation.y = -angle + Math.PI / 2;
      this.mandviGroup.add(disc);
    }

    // Sacred Flickering 3D Diya Flame
    const flameGeo = new THREE.ConeGeometry(0.32, 1.1, 16);
    flameGeo.translate(0, 0.55, 0);
    this.flameMat = new THREE.MeshBasicMaterial({
      color: 0xffec99,
      transparent: true,
      opacity: 0.92
    });
    this.flameMesh = new THREE.Mesh(flameGeo, this.flameMat);
    this.flameMesh.position.y = 5.4;
    this.mandviGroup.add(this.flameMesh);

    // Holy Diya Plate at Top
    const diyaPlate = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.3, 0.2, 24), new THREE.MeshStandardMaterial({
      color: 0xd4af37,
      metalness: 0.8,
      roughness: 0.3
    }));
    diyaPlate.position.y = 5.3;
    this.mandviGroup.add(diyaPlate);

    this.scene.add(this.mandviGroup);
  }

  /* ─────────────────────────────────────────────────────────────
     Dynamic Rangoli Floor & Circular Seek Progress Ring
     ───────────────────────────────────────────────────────────── */

  buildFloor() {
    const floorRadius = 26;

    // Procedural High-Res Rangoli Canvas Texture
    this.floorCanvas = document.createElement('canvas');
    this.floorCanvas.width = 1024;
    this.floorCanvas.height = 1024;
    this.paintFloorCanvas();

    this.floorTexture = new THREE.CanvasTexture(this.floorCanvas);
    this.floorTexture.anisotropy = 16;

    const floorMat = new THREE.MeshStandardMaterial({
      map: this.floorTexture,
      roughness: 0.7,
      metalness: 0.15
    });

    const floorGeo = new THREE.CylinderGeometry(floorRadius, floorRadius, 0.4, 64);
    this.floorMesh = new THREE.Mesh(floorGeo, floorMat);
    this.floorMesh.position.y = -0.2;
    this.floorMesh.receiveShadow = true;
    this.scene.add(this.floorMesh);

    // Glowing Circular Seek Progress Ring
    const ringGeo = new THREE.RingGeometry(21.2, 21.8, 96);
    this.progressRingMat = new THREE.MeshBasicMaterial({
      color: 0xe8557f,
      side: THREE.DoubleSide,
      transparent: true,
      opacity: 0.85
    });
    this.progressRingMesh = new THREE.Mesh(ringGeo, this.progressRingMat);
    this.progressRingMesh.rotation.x = -Math.PI / 2;
    this.progressRingMesh.position.y = 0.02;
    this.scene.add(this.progressRingMesh);

    // Decorative Outer Border Ring with Abla Mirror Sequins
    const outerRingGeo = new THREE.RingGeometry(25.4, 25.8, 64);
    const outerRingMat = new THREE.MeshStandardMaterial({
      color: 0xd4af37,
      metalness: 0.9,
      roughness: 0.15,
      side: THREE.DoubleSide
    });
    const outerBorder = new THREE.Mesh(outerRingGeo, outerRingMat);
    outerBorder.rotation.x = -Math.PI / 2;
    outerBorder.position.y = 0.015;
    this.scene.add(outerBorder);

    // 48 Real Shimmering Mirror Discs (Abla) placed along the floor ring
    const ablaGroup = new THREE.Group();
    const ablaCount = 48;
    const ablaMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.98,
      roughness: 0.05
    });
    for (let i = 0; i < ablaCount; i++) {
      const angle = (i / ablaCount) * Math.PI * 2;
      const abla = new THREE.Mesh(new THREE.CircleGeometry(0.28, 16), ablaMat);
      abla.position.set(Math.cos(angle) * 23.5, 0.03, Math.sin(angle) * 23.5);
      abla.rotation.x = -Math.PI / 2;
      ablaGroup.add(abla);
    }
    this.scene.add(ablaGroup);
  }

  paintFloorCanvas() {
    const ctx = this.floorCanvas.getContext('2d');
    const w = this.floorCanvas.width;
    const h = this.floorCanvas.height;
    const cx = w / 2;
    const cy = h / 2;

    const p = this.theme ? this.theme.palette : {
      bg: '#540D17',
      primary: '#D4A93C',
      secondary: '#E8557F',
      accent: '#2E7D53',
      text: '#F5E7CF'
    };

    // 1. Background Fill
    ctx.fillStyle = p.bg;
    ctx.fillRect(0, 0, w, h);

    // 2. Concentric Sacred Rangoli & Weave Motifs
    ctx.save();
    ctx.translate(cx, cy);

    // Bandhani Dots / Patola Weave concentric tracks
    const ringRadii = [100, 180, 260, 340, 420, 480];
    ringRadii.forEach((r, idx) => {
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.strokeStyle = idx % 2 === 0 ? p.primary : p.secondary;
      ctx.lineWidth = idx === 4 ? 6 : 2.5;
      ctx.setLineDash(idx % 2 === 1 ? [8, 10] : []);
      ctx.stroke();

      // Bandhani dots / Lotus petals on rings
      const numDots = Math.floor(r / 7);
      for (let i = 0; i < numDots; i++) {
        const theta = (i / numDots) * Math.PI * 2;
        const dx = Math.cos(theta) * r;
        const dy = Math.sin(theta) * r;
        ctx.beginPath();
        ctx.arc(dx, dy, idx === 3 ? 4 : 2.5, 0, Math.PI * 2);
        ctx.fillStyle = i % 2 === 0 ? p.primary : p.text;
        ctx.fill();
      }
    });

    // 3. Central 16-Petal Mandala Lotus
    const petals = 16;
    for (let i = 0; i < petals; i++) {
      ctx.save();
      ctx.rotate((i / petals) * Math.PI * 2);
      ctx.beginPath();
      ctx.moveTo(0, 30);
      ctx.bezierCurveTo(40, 70, 30, 140, 0, 175);
      ctx.bezierCurveTo(-30, 140, -40, 70, 0, 30);
      ctx.fillStyle = i % 2 === 0 ? p.primary : p.secondary;
      ctx.globalAlpha = 0.75;
      ctx.fill();
      ctx.strokeStyle = p.text;
      ctx.lineWidth = 1.5;
      ctx.stroke();
      ctx.restore();
    }

    // 4. 8-Pointed Star of Lakshmi / Astha Lakshmi Chowk
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const r = i % 2 === 0 ? 250 : 210;
      const x = Math.cos(a) * r;
      const y = Math.sin(a) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.strokeStyle = p.primary;
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.restore();
  }

  /* ─────────────────────────────────────────────────────────────
     Concentric Rings of 3D Stylized Dancers
     ───────────────────────────────────────────────────────────── */

  buildDancers() {
    this.dancerGroup = new THREE.Group();
    this.scene.add(this.dancerGroup);

    // 3 Rings: Inner (r=7.5, 12 dancers), Middle (r=13.5, 20 dancers), Outer (r=19.5, 28 dancers) = 60 Interactive 3D Dancers!
    const ringConfigs = [
      { radius: 7.5, count: 12, speed: 0.35, dir: 1, step: 'Tran Taali' },
      { radius: 13.5, count: 20, speed: -0.28, dir: -1, step: 'Dodhiya' },
      { radius: 19.5, count: 28, speed: 0.22, dir: 1, step: 'Dandiya Raas' }
    ];

    const names = [
      'Radha', 'Keshav', 'Meera', 'Gopaldas', 'Kinjal', 'Devang', 'Bhavna', 'Hiren',
      'Pooja', 'Jignesh', 'Ami', 'Parth', 'Kavita', 'Manan', 'Dipti', 'Sanjay',
      'Hetal', 'Ketan', 'Jhanvi', 'Bhavesh', 'Tanvi', 'Chirag', 'Riddhi', 'Darshan',
      'Ila', 'Nilesh', 'Alka', 'Kamlesh', 'Vandana', 'Paresh', 'Nirali', 'Mayur'
    ];

    const cities = ['Ahmedabad', 'Vadodara (United Way)', 'Surat', 'Rajkot', 'Kutch', 'Bhavnagar', 'Jamnagar', 'Patan'];

    let nameIdx = 0;
    ringConfigs.forEach((rc, ringIdx) => {
      for (let i = 0; i < rc.count; i++) {
        const baseAngle = (i / rc.count) * Math.PI * 2;
        const isFemale = (i + ringIdx) % 2 === 0;

        const dancer = this.createDancerMesh({
          isFemale,
          ringIdx,
          name: names[nameIdx % names.length],
          city: cities[nameIdx % cities.length],
          step: rc.step
        });

        dancer.userData = {
          ringIdx,
          radius: rc.radius,
          baseAngle,
          angle: baseAngle,
          speed: rc.speed,
          dir: rc.dir,
          bobPhase: Math.random() * Math.PI * 2,
          isFemale,
          name: names[nameIdx % names.length],
          city: cities[nameIdx % cities.length],
          step: rc.step
        };

        this.positionDancer(dancer);
        this.dancerGroup.add(dancer);
        this.dancers.push(dancer);

        nameIdx++;
      }
    });
  }

  createDancerMesh({ isFemale, ringIdx, name }) {
    const dancer = new THREE.Group();

    // Vibrant traditional palette combinations
    const outfitColors = [
      { main: 0xc4245a, accent: 0xffd84d, dhol: 0x00d4ff }, // Rani Pink & Turmeric Gold
      { main: 0x0e3b32, accent: 0xe7c468, dhol: 0xe8557f }, // Peacock Emerald & Lurex
      { main: 0x7a1522, accent: 0xf5e7cf, dhol: 0x3fb0c9 }, // Chunari Red & Ivory
      { main: 0x4a1180, accent: 0xff6a1f, dhol: 0xb6ff3c }, // Royal Purple & Saffron
      { main: 0x1b3a5c, accent: 0xd4a93c, dhol: 0xd6285a }, // Patola Indigo & Gold
      { main: 0xe5197f, accent: 0x00a0c6, dhol: 0xf5a81c }  // Magenta & Cyan
    ];
    const outfit = outfitColors[(dancer.id || Math.floor(Math.random() * 100)) % outfitColors.length];

    const skinMat = new THREE.MeshStandardMaterial({ color: 0xdf9a68, roughness: 0.8 });
    const hairMat = new THREE.MeshStandardMaterial({ color: 0x18100c, roughness: 0.9 });

    // 1. Head & Face
    const head = new THREE.Mesh(new THREE.SphereGeometry(0.34, 16, 14), skinMat);
    head.position.y = 3.3;
    head.castShadow = true;
    dancer.add(head);

    // Hair / Turban
    if (isFemale) {
      // Long braided hair with golden parandi
      const hair = new THREE.Mesh(new THREE.SphereGeometry(0.36, 16, 14), hairMat);
      hair.position.set(0, 3.35, -0.08);
      dancer.add(hair);

      const braid = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.04, 1.2, 8), hairMat);
      braid.position.set(0, 2.7, -0.32);
      braid.rotation.x = -0.2;
      dancer.add(braid);

      // Ornate Maang Tikka
      const tikka = new THREE.Mesh(new THREE.DodecahedronGeometry(0.06), new THREE.MeshBasicMaterial({ color: 0xffd700 }));
      tikka.position.set(0, 3.52, 0.32);
      dancer.add(tikka);
    } else {
      // Gujarati Paghdi / Turban with Bandhani twist
      const turban = new THREE.Mesh(new THREE.TorusGeometry(0.38, 0.16, 12, 24), new THREE.MeshStandardMaterial({
        color: outfit.accent,
        roughness: 0.6
      }));
      turban.position.set(0, 3.48, 0);
      turban.rotation.x = Math.PI / 2 + 0.1;
      dancer.add(turban);

      const turbanTop = new THREE.Mesh(new THREE.SphereGeometry(0.28, 12, 12), new THREE.MeshStandardMaterial({
        color: outfit.main,
        roughness: 0.6
      }));
      turbanTop.position.set(0, 3.65, 0);
      dancer.add(turbanTop);
    }

    // 2. Torso / Choli or Kediyu
    const torsoMat = new THREE.MeshStandardMaterial({
      color: outfit.main,
      roughness: 0.45,
      metalness: 0.2
    });
    const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.38, 1.1, 16), torsoMat);
    torso.position.y = 2.4;
    torso.castShadow = true;
    dancer.add(torso);

    // 3. Lower Costume: Flared Ghaghra (Female) or Kediyu Frill & Dhoti (Male)
    if (isFemale) {
      // Wide flared swirling Chaniya / Ghaghra
      const skirtGeo = new THREE.ConeGeometry(1.25, 1.7, 24, 1, true);
      const skirtMat = new THREE.MeshStandardMaterial({
        color: outfit.main,
        roughness: 0.4,
        metalness: 0.25,
        side: THREE.DoubleSide
      });
      const skirt = new THREE.Mesh(skirtGeo, skirtMat);
      skirt.position.y = 1.05;
      skirt.castShadow = true;
      dancer.add(skirt);
      dancer.skirtMesh = skirt; // for spin animation

      // Mirror-work (Abla) & Golden Border on Skirt Rim
      const border = new THREE.Mesh(new THREE.TorusGeometry(1.24, 0.08, 8, 32), new THREE.MeshStandardMaterial({
        color: outfit.accent,
        metalness: 0.8,
        roughness: 0.2
      }));
      border.position.y = 0.25;
      border.rotation.x = Math.PI / 2;
      dancer.add(border);

      // Translucent Flowing Dupatta / Odhani over shoulder
      const dupattaGeo = new THREE.PlaneGeometry(0.7, 2.2, 4, 8);
      const dupattaMat = new THREE.MeshStandardMaterial({
        color: outfit.accent,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.8
      });
      const dupatta = new THREE.Mesh(dupattaGeo, dupattaMat);
      dupatta.position.set(0.35, 2.1, 0.1);
      dupatta.rotation.z = -0.4;
      dupatta.rotation.y = 0.3;
      dancer.add(dupatta);
    } else {
      // Kediyu Pleated Frill
      const frill = new THREE.Mesh(new THREE.ConeGeometry(0.85, 0.7, 16, 1, true), new THREE.MeshStandardMaterial({
        color: outfit.main,
        side: THREE.DoubleSide
      }));
      frill.position.y = 1.7;
      dancer.add(frill);

      // Traditional Dhoti / Chorno (Gathered White/Ivory Trousers)
      const dhotiMat = new THREE.MeshStandardMaterial({ color: 0xf5eedc, roughness: 0.7 });
      const leftLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.14, 1.6, 12), dhotiMat);
      leftLeg.position.set(-0.24, 0.8, 0);
      dancer.add(leftLeg);

      const rightLeg = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.14, 1.6, 12), dhotiMat);
      rightLeg.position.set(0.24, 0.8, 0);
      dancer.add(rightLeg);
    }

    // 4. Dual 3D Dandiya Sticks
    dancer.dandiyaLeft = this.createDandiyaStick(outfit.accent);
    dancer.dandiyaLeft.position.set(-0.48, 2.2, 0.45);
    dancer.dandiyaLeft.rotation.set(0.4, 0.2, -0.6);
    dancer.add(dancer.dandiyaLeft);

    dancer.dandiyaRight = this.createDandiyaStick(outfit.dhol);
    dancer.dandiyaRight.position.set(0.48, 2.2, 0.45);
    dancer.dandiyaRight.rotation.set(0.4, -0.2, 0.6);
    dancer.add(dancer.dandiyaRight);

    // Give dancer an interactive aura outline mesh (hidden by default)
    const auraGeo = new THREE.CylinderGeometry(1.4, 1.4, 3.8, 16);
    const auraMat = new THREE.MeshBasicMaterial({
      color: 0xffd700,
      wireframe: true,
      transparent: true,
      opacity: 0
    });
    dancer.aura = new THREE.Mesh(auraGeo, auraMat);
    dancer.aura.position.y = 1.9;
    dancer.add(dancer.aura);

    return dancer;
  }

  createDandiyaStick(colorHex) {
    const stickGroup = new THREE.Group();

    // Wooden shaft
    const shaft = new THREE.Mesh(
      new THREE.CylinderGeometry(0.035, 0.035, 1.1, 12),
      new THREE.MeshStandardMaterial({ color: colorHex, metalness: 0.6, roughness: 0.3 })
    );
    stickGroup.add(shaft);

    // Decorative golden metallic band
    const band = new THREE.Mesh(
      new THREE.CylinderGeometry(0.042, 0.042, 0.25, 12),
      new THREE.MeshStandardMaterial({ color: 0xffd700, metalness: 0.9, roughness: 0.15 })
    );
    band.position.y = 0.2;
    stickGroup.add(band);

    // Hanging Ghunghroo / Silk Tassel at tip
    const tassel = new THREE.Mesh(
      new THREE.SphereGeometry(0.065, 8, 8),
      new THREE.MeshBasicMaterial({ color: 0xff3366 })
    );
    tassel.position.y = 0.55;
    stickGroup.add(tassel);

    return stickGroup;
  }

  positionDancer(dancer) {
    const { radius, angle } = dancer.userData;
    dancer.position.x = Math.cos(angle) * radius;
    dancer.position.z = Math.sin(angle) * radius;

    // Face tangent or slightly inwards to the holy Garbi
    dancer.rotation.y = -angle + Math.PI / 2 + (dancer.userData.dir > 0 ? 0.35 : -0.35);
  }

  /* ─────────────────────────────────────────────────────────────
     Atmospheric Particles (Floating Marigold Petals & Sparks)
     ───────────────────────────────────────────────────────────── */

  buildAtmosphere() {
    // 1. Floating Marigold Petals (Genda Phool)
    const petalCount = 180;
    const petalGeo = new THREE.BufferGeometry();
    const pos = new Float32Array(petalCount * 3);
    const colors = new Float32Array(petalCount * 3);

    const petalPalette = [
      new THREE.Color(0xff8c00),
      new THREE.Color(0xffa500),
      new THREE.Color(0xffd700),
      new THREE.Color(0xff4500)
    ];

    for (let i = 0; i < petalCount; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 50;
      pos[i * 3 + 1] = Math.random() * 18 + 0.5;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 50;

      const c = petalPalette[i % petalPalette.length];
      colors[i * 3] = c.r;
      colors[i * 3 + 1] = c.g;
      colors[i * 3 + 2] = c.b;
    }

    petalGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    petalGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));

    const petalMat = new THREE.PointsMaterial({
      size: 0.35,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });

    this.petalParticles = new THREE.Points(petalGeo, petalMat);
    this.scene.add(this.petalParticles);

    // 2. Rising Holy Sparks from the Diya flame
    const sparkCount = 60;
    const sparkGeo = new THREE.BufferGeometry();
    const sparkPos = new Float32Array(sparkCount * 3);
    for (let i = 0; i < sparkCount; i++) {
      sparkPos[i * 3] = (Math.random() - 0.5) * 0.8;
      sparkPos[i * 3 + 1] = 5.4 + Math.random() * 4;
      sparkPos[i * 3 + 2] = (Math.random() - 0.5) * 0.8;
    }
    sparkGeo.setAttribute('position', new THREE.BufferAttribute(sparkPos, 3));
    this.sparkParticles = new THREE.Points(sparkGeo, new THREE.PointsMaterial({
      color: 0xffd24d,
      size: 0.18,
      transparent: true,
      opacity: 0.9
    }));
    this.scene.add(this.sparkParticles);
  }

  /* ─────────────────────────────────────────────────────────────
     Interaction & Camera Controls
     ───────────────────────────────────────────────────────────── */

  setupEvents() {
    window.addEventListener('resize', () => this.onResize());

    const dom = this.renderer.domElement;

    // Mouse / Touch Drag for Smooth Orbit Controls
    dom.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      this.prevMousePos = { x: e.clientX, y: e.clientY };
    });

    window.addEventListener('mouseup', () => {
      this.isDragging = false;
    });

    dom.addEventListener('mousemove', (e) => {
      if (this.isDragging) {
        const dx = e.clientX - this.prevMousePos.x;
        const dy = e.clientY - this.prevMousePos.y;
        this.spherical.theta -= dx * 0.006;
        this.spherical.phi = Math.max(0.15, Math.min(Math.PI / 2 - 0.05, this.spherical.phi - dy * 0.006));
        this.updateCameraFromSpherical();
        this.prevMousePos = { x: e.clientX, y: e.clientY };
      }
    });

    // Scroll Zoom
    dom.addEventListener('wheel', (e) => {
      e.preventDefault();
      this.spherical.radius = Math.max(8, Math.min(65, this.spherical.radius + e.deltaY * 0.04));
      this.updateCameraFromSpherical();
    }, { passive: false });

    // Click Detection for Dancers & Floor Seeking
    dom.addEventListener('click', (e) => {
      const rect = dom.getBoundingClientRect();
      this.mouse.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      this.mouse.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

      this.raycaster.setFromCamera(this.mouse, this.camera);

      // Check dancer click
      const dancerIntersects = this.raycaster.intersectObjects(this.dancerGroup.children, true);
      if (dancerIntersects.length > 0) {
        let root = dancerIntersects[0].object;
        while (root.parent && root.parent !== this.dancerGroup) {
          root = root.parent;
        }
        if (root && root.userData && root.userData.name) {
          this.highlightDancer(root);
          if (this.onDancerClick) {
            this.onDancerClick(root.userData);
          }
          return;
        }
      }

      // Check floor seek click
      const floorIntersects = this.raycaster.intersectObject(this.floorMesh);
      if (floorIntersects.length > 0) {
        const pt = floorIntersects[0].point;
        const dist = Math.sqrt(pt.x * pt.x + pt.z * pt.z);
        if (dist > 18 && dist < 24) {
          // Calculate angle fraction
          let angle = Math.atan2(pt.z, pt.x);
          if (angle < 0) angle += Math.PI * 2;
          const fraction = angle / (Math.PI * 2);
          if (this.onFloorSeek) this.onFloorSeek(fraction);
        }
      }
    });
  }

  updateCameraFromSpherical() {
    const { radius, theta, phi } = this.spherical;
    this.camera.position.x = this.cameraTarget.x + radius * Math.sin(phi) * Math.sin(theta);
    this.camera.position.y = this.cameraTarget.y + radius * Math.cos(phi);
    this.camera.position.z = this.cameraTarget.z + radius * Math.sin(phi) * Math.cos(theta);
    this.camera.lookAt(this.cameraTarget);
  }

  setCameraPreset(mode) {
    this.cameraMode = mode;
    if (mode === 'arena') {
      this.cameraTarget.set(0, 2.5, 0);
      this.spherical = { radius: 36, theta: Math.PI / 4, phi: Math.PI / 3 };
    } else if (mode === 'mandvi') {
      this.cameraTarget.set(0, 3.8, 0);
      this.spherical = { radius: 10, theta: 0.2, phi: Math.PI / 2.6 };
    } else if (mode === 'dancer') {
      this.cameraTarget.set(8, 2.2, 0);
      this.spherical = { radius: 14, theta: -Math.PI / 3, phi: Math.PI / 2.3 };
    } else if (mode === 'topdown') {
      this.cameraTarget.set(0, 0, 0);
      this.spherical = { radius: 44, theta: 0, phi: 0.08 };
    }
    this.updateCameraFromSpherical();
  }

  highlightDancer(dancer) {
    // Flash celebratory aura and perform spin
    dancer.aura.material.opacity = 0.85;
    dancer.isCelebrating = true;
    dancer.celebrateStart = performance.now();

    setTimeout(() => {
      dancer.aura.material.opacity = 0;
      dancer.isCelebrating = false;
    }, 2800);
  }

  addCustomUserAvatar({ name, gender, clothTheme, dandiyaColor }) {
    const isFemale = gender === 'female';
    const avatar = this.createDancerMesh({
      isFemale,
      ringIdx: 2,
      name: name || 'Aapde Khelaiya'
    });

    avatar.userData = {
      ringIdx: 2,
      radius: 20.8,
      baseAngle: 0,
      angle: 0,
      speed: 0.22,
      dir: 1,
      bobPhase: 0,
      isFemale,
      name: `${name} (You!)`,
      city: 'Gujarat Heritage Circle',
      step: 'Garba Queen / King Step'
    };

    if (this.userAvatar) {
      this.dancerGroup.remove(this.userAvatar);
    }

    this.userAvatar = avatar;
    this.dancerGroup.add(avatar);
    this.dancers.push(avatar);

    this.highlightDancer(avatar);
    this.setCameraPreset('dancer');
  }

  /* ─────────────────────────────────────────────────────────────
     Theme & Playback Synchronization
     ───────────────────────────────────────────────────────────── */

  setTheme(theme) {
    this.theme = theme;
    this.paintFloorCanvas();
    if (this.floorTexture) {
      this.floorTexture.needsUpdate = true;
    }

    // Update Diya Light and Fog color to match cloth ambience
    if (this.scene.fog && theme.palette) {
      const fogHex = parseInt(theme.palette.bg.replace('#', '0x'));
      this.scene.fog.color.setHex(fogHex);
      this.renderer.setClearColor(fogHex);
    }
    if (this.progressRingMat && theme.palette) {
      this.progressRingMat.color.set(theme.palette.ringColor || 0xe8557f);
    }
  }

  setBpm(bpm) {
    this.bpm = bpm || 118;
  }

  setPlaying(on) {
    this.isPlaying = on;
  }

  setProgress(fraction) {
    this.progress = Math.max(0, Math.min(1, fraction));
  }

  setCrowd(n) {
    this.crowdCount = n;
  }

  onResize() {
    if (!this.container || !this.renderer || !this.camera) return;
    const w = this.container.clientWidth;
    const h = this.container.clientHeight;
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
    this.renderer.setSize(w, h);
  }

  /* ─────────────────────────────────────────────────────────────
     Animation Loop
     ───────────────────────────────────────────────────────────── */

  animate() {
    this.animId = requestAnimationFrame(this.animate);

    const dt = this.clock.getDelta();
    const elapsedTime = this.clock.getElapsedTime();

    // 1. Diya Flame & Point Light Flicker
    if (this.flameMesh && this.diyaLight) {
      const flicker = Math.sin(elapsedTime * 18) * 0.08 + Math.cos(elapsedTime * 28) * 0.04;
      this.flameMesh.scale.set(1 + flicker, 1 + flicker * 1.5, 1 + flicker);
      this.diyaLight.intensity = (this.isPlaying ? 4.2 : 3.0) + Math.sin(elapsedTime * 15) * 0.6;
    }

    // 2. Animate Dancers to Song BPM
    const beatSec = 60 / this.bpm;
    const beatPhase = (elapsedTime % beatSec) / beatSec; // 0..1 per beat

    const moveMultiplier = this.isPlaying ? 1.0 : 0.25;

    this.dancers.forEach((dancer) => {
      const u = dancer.userData;

      // Orbit along circle
      u.angle += u.speed * dt * moveMultiplier * (this.bpm / 118);
      dancer.position.x = Math.cos(u.angle) * u.radius;
      dancer.position.z = Math.sin(u.angle) * u.radius;

      // Rhythmic Knee Bend & Bounce on Dhol Beat
      const bounce = Math.abs(Math.sin(beatPhase * Math.PI)) * 0.35 * moveMultiplier;
      dancer.position.y = bounce;

      // Swirling Dandiya Clack Strike
      const clackSwing = Math.sin(beatPhase * Math.PI * 2) * 0.45 * moveMultiplier;
      dancer.dandiyaLeft.rotation.z = -0.6 + clackSwing;
      dancer.dandiyaRight.rotation.z = 0.6 - clackSwing;

      // Body sway and facing direction
      dancer.rotation.y = -u.angle + Math.PI / 2 + (u.dir > 0 ? 0.3 : -0.3) + Math.sin(beatPhase * Math.PI) * 0.15;

      // Skirt flare when swirling
      if (dancer.skirtMesh) {
        dancer.skirtMesh.rotation.y += dt * u.dir * 3.5 * moveMultiplier;
      }

      // Celebratory spin when clicked
      if (dancer.isCelebrating) {
        dancer.rotation.y += dt * 14;
      }
    });

    // 3. Update Progress Ring
    if (this.progressRingMesh) {
      // Rotate ring or pulse opacity
      this.progressRingMesh.rotation.z = -this.progress * Math.PI * 2;
    }

    // 4. Animate Floating Marigold Petals
    if (this.petalParticles) {
      const pos = this.petalParticles.geometry.attributes.position.array;
      for (let i = 0; i < pos.length / 3; i++) {
        pos[i * 3 + 1] -= dt * 0.9; // gently fall
        pos[i * 3] += Math.sin(elapsedTime + i) * dt * 0.4;
        if (pos[i * 3 + 1] < 0) {
          pos[i * 3 + 1] = 18;
        }
      }
      this.petalParticles.geometry.attributes.position.needsUpdate = true;
      this.petalParticles.rotation.y += dt * 0.04;
    }

    // 5. Animate Holy Sparks from Diya
    if (this.sparkParticles) {
      const sp = this.sparkParticles.geometry.attributes.position.array;
      for (let i = 0; i < sp.length / 3; i++) {
        sp[i * 3 + 1] += dt * 2.2;
        sp[i * 3] += (Math.random() - 0.5) * 0.03;
        if (sp[i * 3 + 1] > 9.5) {
          sp[i * 3 + 1] = 5.4;
          sp[i * 3] = (Math.random() - 0.5) * 0.8;
          sp[i * 3 + 2] = (Math.random() - 0.5) * 0.8;
        }
      }
      this.sparkParticles.geometry.attributes.position.needsUpdate = true;
    }

    // 6. Slowly orbit camera if in cinematic arena view and user is not dragging
    if (this.cameraMode === 'arena' && !this.isDragging && this.isPlaying) {
      this.spherical.theta += dt * 0.04;
      this.updateCameraFromSpherical();
    }

    this.renderer.render(this.scene, this.camera);
  }

  destroy() {
    if (this.animId) cancelAnimationFrame(this.animId);
    if (this.renderer && this.renderer.domElement) {
      this.renderer.domElement.remove();
    }
  }
}
